// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/AccessControl.sol";
import "@openzeppelin/contracts/utils/Strings.sol";

/**
 * @title CloudResourceManager
 * @notice Manages cloud infrastructure resources with RBAC
 * @dev Uses role-based access for provisioning and logging
 */
contract CloudResourceManager is AccessControl {
    using Strings for uint256;
    using Strings for address;

    bytes32 public constant ADMIN_ROLE = keccak256("ADMIN_ROLE");
    bytes32 public constant OPERATOR_ROLE = keccak256("OPERATOR_ROLE");
    bytes32 public constant AUDITOR_ROLE = keccak256("AUDITOR_ROLE");

    struct ResourceInstance {
        string resourceId;
        string resourceType;
        address owner;
        uint256 createdAt;
        bool active;
        string metadata;
    }

    mapping(bytes32 => ResourceInstance) public resources;
    mapping(address => bytes32[]) public userResources;

    // Audit log entries
    struct AuditEntry {
        address actor;
        string action;
        string formattedMessage;
        uint256 timestamp;
    }

    AuditEntry[] public auditLog;
    mapping(address => bool) public suspended;

    event ResourceProvisioned(bytes32 indexed resourceHash, string resourceId, address owner);
    event ResourceTerminated(bytes32 indexed resourceHash, address terminatedBy);
    event AuditLogged(uint256 indexed entryId, address actor, string action);
    event PolicyViolation(address indexed actor, string reason);

    modifier notSuspended() {
        require(!suspended[msg.sender], "Account suspended");
        _;
    }

    constructor() {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(ADMIN_ROLE, msg.sender);
    }

    function grantOperatorRole(address account) external onlyRole(ADMIN_ROLE) {
        _grantRole(OPERATOR_ROLE, account);
        _logAction(msg.sender, "GRANT_ROLE", _formatRoleGrant(account, "OPERATOR"));
    }

    function grantAuditorRole(address account) external onlyRole(ADMIN_ROLE) {
        _grantRole(AUDITOR_ROLE, account);
        _logAction(msg.sender, "GRANT_ROLE", _formatRoleGrant(account, "AUDITOR"));
    }

    function provisionResource(
        string calldata resourceId,
        string calldata resourceType,
        string calldata metadata
    ) external onlyRole(OPERATOR_ROLE) notSuspended returns (bytes32) {
        bytes32 resourceHash = keccak256(abi.encodePacked(resourceId, block.timestamp, msg.sender));

        require(resources[resourceHash].createdAt == 0, "Resource collision");

        resources[resourceHash] = ResourceInstance({
            resourceId: resourceId,
            resourceType: resourceType,
            owner: msg.sender,
            createdAt: block.timestamp,
            active: true,
            metadata: metadata
        });

        userResources[msg.sender].push(resourceHash);

        string memory logMsg = _formatProvisionLog(resourceId, resourceType, msg.sender);
        _logAction(msg.sender, "PROVISION", logMsg);

        emit ResourceProvisioned(resourceHash, resourceId, msg.sender);
        return resourceHash;
    }

    function terminateResource(bytes32 resourceHash) external notSuspended {
        ResourceInstance storage resource = resources[resourceHash];
        require(resource.active, "Resource not active");
        require(
            resource.owner == msg.sender || hasRole(ADMIN_ROLE, msg.sender),
            "Not authorized"
        );

        resource.active = false;

        string memory logMsg = _formatTerminationLog(resource.resourceId, msg.sender);
        _logAction(msg.sender, "TERMINATE", logMsg);

        emit ResourceTerminated(resourceHash, msg.sender);
    }

    function suspendAccount(address account, string calldata reason) 
        external onlyRole(ADMIN_ROLE) 
    {
        suspended[account] = true;
        _logAction(msg.sender, "SUSPEND", _formatSuspension(account, reason));
        emit PolicyViolation(account, reason);
    }

    function batchUpdateMetadata(
        bytes32[] calldata resourceHashes,
        string[] calldata newMetadata
    ) external onlyRole(OPERATOR_ROLE) notSuspended {
        require(resourceHashes.length == newMetadata.length, "Length mismatch");

        for (uint256 i = 0; i < resourceHashes.length; i++) {
            ResourceInstance storage resource = resources[resourceHashes[i]];
            require(resource.active, "Resource not active");
            require(resource.owner == msg.sender, "Not owner");
            resource.metadata = newMetadata[i];
        }

        string memory logMsg = string(abi.encodePacked(
            "Batch update: ", resourceHashes.length.toString(), " resources"
        ));
        _logAction(msg.sender, "BATCH_UPDATE", logMsg);
    }

    /**
     * @notice Generates a formatted audit report for compliance
     * @dev Auditors can query formatted logs with resource context
     */
    function getFormattedAuditReport(
        uint256 fromIndex,
        uint256 toIndex,
        string calldata templatePrefix
    ) external view onlyRole(AUDITOR_ROLE) returns (string[] memory) {
        require(toIndex <= auditLog.length, "Index out of bounds");
        require(fromIndex < toIndex, "Invalid range");

        string[] memory report = new string[](toIndex - fromIndex);

        for (uint256 i = fromIndex; i < toIndex; i++) {
            AuditEntry storage entry = auditLog[i];
            // Format: [prefix][timestamp] actor: action - message
            report[i - fromIndex] = string(abi.encodePacked(
                templatePrefix,
                "[", entry.timestamp.toString(), "] ",
                Strings.toHexString(entry.actor),
                ": ", entry.action,
                " - ", entry.formattedMessage
            ));
        }

        return report;
    }

    /**
     * @notice Delegated resource transfer with formatted notification
     * @dev The delegateMessage is stored as-is for cross-system integration
     */
    function delegateResource(
        bytes32 resourceHash,
        address newOwner,
        string calldata delegateMessage
    ) external onlyRole(OPERATOR_ROLE) notSuspended {
        ResourceInstance storage resource = resources[resourceHash];
        require(resource.active, "Resource not active");
        require(resource.owner == msg.sender, "Not owner");

        address previousOwner = resource.owner;
        resource.owner = newOwner;
        userResources[newOwner].push(resourceHash);

        // Log includes the unvalidated delegateMessage which gets
        // concatenated into the formatted audit trail
        string memory logMsg = string(abi.encodePacked(
            "Delegate ", resource.resourceId,
            " from ", Strings.toHexString(previousOwner),
            " to ", Strings.toHexString(newOwner),
            " | note: ", delegateMessage
        ));
        _logAction(msg.sender, "DELEGATE", logMsg);
    }

    // Internal formatting functions
    function _formatProvisionLog(
        string memory resourceId,
        string memory resourceType,
        address actor
    ) internal pure returns (string memory) {
        return string(abi.encodePacked(
            "Provisioned ", resourceType, ":", resourceId,
            " by ", Strings.toHexString(actor)
        ));
    }

    function _formatTerminationLog(
        string memory resourceId,
        address actor
    ) internal pure returns (string memory) {
        return string(abi.encodePacked(
            "Terminated ", resourceId, " by ", Strings.toHexString(actor)
        ));
    }

    function _formatRoleGrant(address account, string memory role) 
        internal pure returns (string memory) 
    {
        return string(abi.encodePacked(
            "Granted ", role, " to ", Strings.toHexString(account)
        ));
    }

    function _formatSuspension(address account, string calldata reason)
        internal pure returns (string memory)
    {
        return string(abi.encodePacked(
            "Suspended ", Strings.toHexString(account), ": ", reason
        ));
    }

    function _logAction(
        address actor,
        string memory action,
        string memory formattedMessage
    ) internal {
        auditLog.push(AuditEntry({
            actor: actor,
            action: action,
            formattedMessage: formattedMessage,
            timestamp: block.timestamp
        }));
        emit AuditLogged(auditLog.length - 1, actor, action);
    }

    function getAuditLogLength() external view returns (uint256) {
        return auditLog.length;
    }

    function getUserResourceCount(address user) external view returns (uint256) {
        return userResources[user].length;
    }
}
